/**
 * The Game Night rules core (Rust, in `core/`) for Node.
 *
 * Every game's rules live in the core; this package loads its WebAssembly
 * build and gives it types. `pkg/` is generated by `pnpm build:wasm`.
 */

import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { initSync, Lookahead, Round, games as gamesJson, layout } from '../pkg/gamelab_wasm.js';

initSync({ module: readFileSync(new URL('../pkg/gamelab_wasm_bg.wasm', import.meta.url)) });

export { Lookahead, Round, layout };

/** One rule of a game, as the lab shows and edits it. */
export interface Setting {
  key: string;
  label: string;
  help: string;
  group: string;
  kind: string;
  min?: number;
  max?: number;
  options?: Array<{ value: string | number; label: string }>;
}

export interface GameInfo {
  id: string;
  number: number;
  minPlayers: number;
  maxPlayers: number;
  settings: Setting[];
  /** Named rule sets; the first is the default. */
  presets: Array<[string, Record<string, unknown>]>;
  verbs: Array<[number, string]>;
  stats: Array<{ key: string; label: string }>;
}

const GAMES: GameInfo[] = JSON.parse(gamesJson());

/** Every game the core knows. */
export function games(): GameInfo[] {
  return GAMES;
}

export function gameInfo(game: string): GameInfo {
  const info = GAMES.find((g) => g.id === game);
  if (!info) throw new Error(`unknown game ${game}`);
  return info;
}

/** A game's named rule set; its default when `name` is not given. */
export function preset<R = Record<string, unknown>>(game: string, name?: string): R {
  const found = gameInfo(game).presets.find(([label]) => name === undefined || label === name);
  if (!found) throw new Error(`${game} has no preset called ${name}`);
  return structuredClone(found[1]) as R;
}

/**
 * Deal a round for people at a table. With `seed` the deal repeats (and
 * matches what the site's original engines dealt for that seed); without it
 * the seed comes from the system's random source.
 */
export function deal(game: string, rules: unknown, players: number, seed?: number): Round {
  if (seed !== undefined) return new Round(game, JSON.stringify(rules), players, 0, seed >>> 0, true, true);
  const b = randomBytes(8);
  return new Round(game, JSON.stringify(rules), players, b.readUInt32LE(0), b.readUInt32LE(4), true, false);
}

/** A round written by `Round.save`. */
export function load(game: string, saved: unknown): Round {
  return Round.load(game, typeof saved === 'string' ? saved : JSON.stringify(saved));
}

/** Apply an action; returns why it was refused, or null. */
export function apply(round: Round, seat: number, action: unknown): string | null {
  return round.apply(seat, JSON.stringify(action)) ?? null;
}

/** Why `apply` would refuse the action, or null, without changing the round. */
export function check(round: Round, seat: number, action: unknown): string | null {
  return round.check(seat, JSON.stringify(action)) ?? null;
}
